import { useEffect, useState, type FormEvent, type ReactNode } from 'react'
import type { QueryClient } from '@tanstack/react-query'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { Link, NavLink, Navigate, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom'
import { api, ApiError, json } from './lib/api'
import { supabase } from './lib/supabase'
import { weekStart } from './lib/date'

type Me={id:string;email?:string|null;workspace_id:string;display_name:string}
type Member={user_id:string;display_name:string;role?:string}
type Settings={workspace_id:string;project_name:string;description?:string|null;stage?:string|null;next_result?:string|null;landing_url?:string|null;telegram_url?:string|null;presentation_file_id?:string|null;updated_at?:string}
type Task={id:string;title:string;description?:string|null;assignee_id?:string|null;status:'planned'|'in_progress'|'done';due_date?:string|null;planned_week?:string|null;blocked:boolean;block_reason?:string|null;updated_at:string}
type Program={id:string;name:string;url?:string|null;deadline?:string|null;status:'considering'|'preparing'|'submitted'|'next_stage'|'accepted'|'rejected';next_step?:string|null;notes?:string|null;archived:boolean;updated_at:string}
type Answer={id:string;question:string;answer:string;keywords:string;updated_at:string}
type FileRow={id:string;display_name:string;original_name:string;mime_type:string;size_bytes:number;scope:'project'|'program';program_id?:string|null;created_at:string;created_by?:string|null}
type EventRow={id:string;title:string;meeting_date:string;notes:string;start_time?:string|null;end_time?:string|null;event_type?:string|null;mode?:string|null;location?:string|null;program_id?:string|null;participants?:string[];updated_at:string}
type Decision={id:string;title:string;text:string;decision_date:string;meeting_id?:string|null;archived:boolean;updated_at:string}
type GithubIssue={id:string;number:number;title:string;state:string;url:string;assignee?:string|null;labels?:unknown;repository_id:string;github_updated_at?:string|null}
type Repo={id:string;full_name:string;last_synced_at?:string|null;last_sync_error?:string|null}
type QuickLink={id:string;title:string;url:string;kind:string;position?:number}
type Feedback={id:string;quote:string;author_name:string;author_role?:string|null;sentiment?:string|null;tags?:string[];created_at:string}
type Metric={metric_date?:string;users_total:number;messages_total:number;dialogs_total:number;weekly_active:number;avg_session_seconds:number;retention_7d:number;registration_conversion:number;changes?:Record<string,number>}
type CommentRow={id:string;body:string;created_by?:string|null;author_name?:string;can_edit?:boolean;created_at:string;updated_at:string}
type ProgramDetail={program:Program;checklist:Array<{id:string;text:string;done:boolean;created_at?:string}>;answers:Array<{id:string;question:string;answer:string;source_answer_id?:string|null;updated_at:string}>;files:Array<{id:string;file_id:string;files:FileRow}>;submissions:Array<{id:string;created_at:string;snapshot:unknown}>}

const statusName:Record<string,string>={planned:'Запланировано',in_progress:'В работе',done:'Готово',considering:'Рассматриваем',preparing:'Готовим',submitted:'Подали',next_stage:'Следующий этап',accepted:'Приняты',rejected:'Отказ'}
const eventNames:Record<string,string>={meeting:'Встреча',interview:'Интервью',demo:'Демо-день',pitch:'Питч',webinar:'Вебинар',consultation:'Консультация',deadline:'Важная дата',external:'Внешнее'}
const roleName:Record<string,string>={cofounder:'Сооснователь',manager:'Менеджер',member:'Участник',guest:'Гость'}
const asset=(name:string)=>`${import.meta.env.BASE_URL}${name}`
const cx=(...v:Array<string|false|undefined|null>)=>v.filter(Boolean).join(' ')
const ruDate=(v?:string|null)=>v?new Date(v+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'}):'—'
const initials=(name:string)=>name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()
const bytes=(n:number)=>n<1024*1024?`${Math.max(1,Math.round(n/1024))} КБ`:`${(n/1024/1024).toFixed(1).replace('.',',')} МБ`

function Icon({name}:{name:string}){const map:Record<string,string>={home:'⌂',tasks:'✓',programs:'▦',answers:'▥',files:'▱',events:'▣',settings:'⚙',search:'⌕',bell:'♢',sun:'☼',plus:'＋',calendar:'□',github:'●',link:'↗',copy:'⧉',more:'⋮',download:'⇩',edit:'✎',trash:'⌫',check:'✓',clock:'◷',users:'♙',message:'◰',chart:'⌁'};return <span className="ico" aria-hidden>{map[name]||'•'}</span>}
function Loading(){return <div className="state"><span className="spinner"/>Загрузка…</div>}
function ErrorBox({error}:{error:unknown}){return <div className="state error">{error instanceof Error?error.message:'Ошибка запроса'}</div>}
function Empty({children}:{children:ReactNode}){return <div className="empty">{children}</div>}
function Avatar({name}:{name:string}){return <span className="avatar">{initials(name||'Д')}</span>}
function Chip({children,tone='green'}:{children:ReactNode;tone?:string}){return <span className={`chip ${tone}`}>{children}</span>}
function Card({title,action,children,className}:{title?:ReactNode;action?:ReactNode;children:ReactNode;className?:string}){return <section className={cx('panel',className)}>{(title||action)&&<div className="panel-head">{title&&<h2>{title}</h2>}{action}</div>}{children}</section>}
function PageTitle({title,subtitle,action}:{title:string;subtitle?:string;action?:ReactNode}){return <div className="page-title"><div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>}
function Dots(){return <button className="icon-btn" title="Действия"><Icon name="more"/></button>}
function Button({children,kind='primary',...props}:{children:ReactNode;kind?:'primary'|'secondary'|'danger'|'ghost'}&React.ButtonHTMLAttributes<HTMLButtonElement>){return <button {...props} className={cx('btn',kind,props.className)}>{children}</button>}

function CommentsPanel({entityType,entityId,compact=false}:{entityType:'answer'|'program_answer'|'file';entityId:string;compact?:boolean}){
 const qc=useQueryClient();const [text,setText]=useState('');const [editingId,setEditingId]=useState<string|null>(null);const [editText,setEditText]=useState('')
 const key=['comments',entityType,entityId]
 const q=useQuery<CommentRow[]>({queryKey:key,enabled:Boolean(entityId),queryFn:()=>api(`/comments?entity_type=${entityType}&entity_id=${encodeURIComponent(entityId)}`)})
 const add=useMutation({mutationFn:()=>api('/comments',json('POST',{entity_type:entityType,entity_id:entityId,body:text.trim()})),onSuccess:()=>{setText('');void qc.invalidateQueries({queryKey:key})}})
 const edit=useMutation({mutationFn:({id,body}:{id:string;body:string})=>api(`/comments/${id}`,json('PATCH',{body})),onSuccess:()=>{setEditingId(null);setEditText('');void qc.invalidateQueries({queryKey:key})}})
 const del=useMutation({mutationFn:(id:string)=>api(`/comments/${id}`,{method:'DELETE'}),onSuccess:()=>void qc.invalidateQueries({queryKey:key})})
 return <section className={cx('comments-panel',compact&&'compact')}><div className="comments-head"><b>Комментарии</b><span>{q.data?.length||0}</span></div>{q.isLoading?<div className="comments-empty">Загрузка…</div>:q.data?.length?<div className="comment-list">{q.data.map(c=><article key={c.id}><div><b>{c.author_name||'Участник'}</b><small>{new Date(c.created_at).toLocaleString('ru-RU')}</small></div>{editingId===c.id?<div className="comment-edit"><textarea rows={2} value={editText} onChange={e=>setEditText(e.target.value)}/><div><button onClick={()=>edit.mutate({id:c.id,body:editText.trim()})} disabled={!editText.trim()}>Сохранить</button><button onClick={()=>setEditingId(null)}>Отмена</button></div></div>:<p>{c.body}</p>}{c.can_edit&&editingId!==c.id&&<footer><button onClick={()=>{setEditingId(c.id);setEditText(c.body)}}>Изменить</button><button onClick={()=>{if(confirm('Удалить комментарий?'))del.mutate(c.id)}}>Удалить</button></footer>}</article>)}</div>:<div className="comments-empty">Комментариев пока нет.</div>}<form className="comment-form" onSubmit={e=>{e.preventDefault();if(text.trim())add.mutate()}}><textarea rows={compact?2:3} value={text} onChange={e=>setText(e.target.value)} placeholder="Комментарий, правка или замечание…"/><Button disabled={!text.trim()||add.isPending}>{add.isPending?'Добавляем…':'Добавить комментарий'}</Button></form></section>
}

function Topbar(){
 const loc=useLocation(),navigate=useNavigate();const [q,setQ]=useState(''),[open,setOpen]=useState(false)
 const me=useQuery<Me>({queryKey:['me'],queryFn:()=>api('/me')});
 const search=useQuery<any>({queryKey:['global-search',q],enabled:q.trim().length>1,queryFn:()=>api(`/search?q=${encodeURIComponent(q.trim())}`)})
 useEffect(()=>{setOpen(false);setQ('')},[loc.pathname])
 const results=search.data?.results||[]
 return <header className="topbar"><div className="global-search"><Icon name="search"/><input value={q} onChange={e=>{setQ(e.target.value);setOpen(true)}} onFocus={()=>setOpen(true)} placeholder="Поиск по задачам, файлам, решениям..."/><kbd>⌘ K</kbd>{open&&q.trim().length>1&&<div className="search-popover">{search.isLoading?<div className="mini-state">Ищем…</div>:results.length?results.slice(0,8).map((r:any)=><button key={`${r.type}-${r.id}`} onClick={()=>navigate(r.href)}><span>{r.title}</span><small>{r.type_label}</small></button>):<div className="mini-state">Ничего не найдено</div>}</div>}</div><div className="top-actions"><button className="icon-btn"><Icon name="sun"/></button><button className="icon-btn notification"><Icon name="bell"/><i/></button><div className="user-menu"><Avatar name={me.data?.display_name||'Друк'}/><div><strong>{me.data?.display_name||'Команда'}</strong><span>Сооснователь</span></div><span>⌄</span></div></div></header>
}

function Sidebar(){const nav=[['/','home','Главная'],['/tasks','tasks','Задачи'],['/programs','programs','Программы'],['/answers','answers','База ответов'],['/files','files','Файлы'],['/events','events','Мероприятия'],['/settings','settings','Настройки']];return <aside className="sidebar"><div className="brand"><span className="leaf">🌱</span><div><strong>Друк</strong><span>Большие дела<br/>в добрых руках</span></div></div><nav>{nav.map(([to,ic,label])=><NavLink key={to} to={to} end={to==='/' }><Icon name={ic}/><span>{label}</span></NavLink>)}</nav><div className="sidebar-art" style={{backgroundImage:`url(${asset('rail.webp')})`}}/></aside>}
function Shell(){return <div className="app-shell"><Sidebar/><div className="workspace"><Topbar/><main className="content"><Routes><Route index element={<DashboardPage/>}/><Route path="tasks" element={<TasksPage/>}/><Route path="programs" element={<ProgramsPage/>}/><Route path="programs/:id" element={<ProgramPage/>}/><Route path="answers" element={<AnswersPage/>}/><Route path="files" element={<FilesPage/>}/><Route path="events" element={<EventsPage/>}/><Route path="settings" element={<SettingsPage/>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes></main></div></div>}

export default function App({queryClient}:{queryClient:QueryClient}){const [ready,setReady]=useState(false),[signed,setSigned]=useState(false);useEffect(()=>{void supabase.auth.getSession().then(({data})=>{setSigned(Boolean(data.session));setReady(true)});const {data}=supabase.auth.onAuthStateChange((_e,s)=>{setSigned(Boolean(s));if(!s)queryClient.clear()});return()=>data.subscription.unsubscribe()},[queryClient]);if(!ready)return <Loading/>;if(!signed)return <Login/>;return <Gate/>}
function Gate(){const q=useQuery<Me>({queryKey:['me'],queryFn:()=>api('/me')});if(q.isLoading)return <Loading/>;if(q.error){const denied=q.error instanceof ApiError&&q.error.status===403;return <div className="auth"><div className="auth-card"><img src={asset('druk.webp')} alt=""/><h1>{denied?'Нет доступа':'Ошибка входа'}</h1><p>{denied?'Ваш аккаунт ещё не добавлен в рабочее пространство.':q.error.message}</p><Button onClick={()=>void supabase.auth.signOut()}>Выйти</Button></div></div>}return <Shell/>}
function Login(){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');const {error:err}=await supabase.auth.signInWithPassword({email,password});if(err)setError(err.message);setBusy(false)}return <div className="auth"><div className="auth-card"><img src={asset('druk.webp')} alt="Друк"/><p className="overline">ВНУТРЕННЕЕ ПРОСТРАНСТВО</p><h1>Друк</h1><p>Задачи, программы, файлы и решения команды в одном месте.</p><form onSubmit={submit}><label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Пароль<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<div className="field-error">{error}</div>}<Button disabled={busy}>{busy?'Входим…':'Войти'}</Button></form></div></div>}

function DashboardPage(){
 const q=useQuery<any>({queryKey:['dashboard-rich'],queryFn:async()=>{const [base,analytics,links,members]=await Promise.all([api('/dashboard'),api('/analytics'),api('/links'),api('/team')]);return {base,analytics,links,members}}});const qc=useQueryClient()
 const focusMut=useMutation({mutationFn:({id,done}:{id:string;done:boolean})=>api(`/focus/${id}`,json('PATCH',{done})),onSuccess:()=>void qc.invalidateQueries({queryKey:['dashboard-rich']})})
 if(q.isLoading)return <Loading/>;if(q.error)return <ErrorBox error={q.error}/>;const {base,analytics,links,members}=q.data;const settings:Settings|undefined=base.settings;const metric:Metric=analytics.metric;const feedback:Feedback[]=analytics.feedback||[]
 return <div className="dashboard-page"><section className="hero home-hero"><div className="hero-copy"><span className="overline">ВМЕСТЕ СОЗДАЁМ БОЛЬШЕ</span><h1>{settings?.project_name||'Друк'}</h1><p>{settings?.description||'Простые инструменты для больших идей. Делаем технологии человечнее.'}</p><div className="hero-stage"><div><small>Текущий этап</small><b>{settings?.stage||'Продуктовая разработка'}</b></div><span>›</span><div><small>Ближайший ожидаемый результат</small><b>{settings?.next_result||'Черновая версия MVP'}</b></div></div></div><div className="hero-visual" style={{backgroundImage:`url(${asset('hero-home.webp')})`}}/></section>
 <div className="dashboard-grid"><Card title="Быстрые ссылки" className="span-2"><div className="quick-links">{(links as QuickLink[]).slice(0,3).map((l,i)=><a key={l.id} href={l.url} target="_blank" rel="noreferrer"><span className={`quick-icon q${i}`}>{l.kind==='telegram'?'➤':l.kind==='presentation'?'▤':'◎'}</span><div><b>{l.title}</b><small>{l.kind==='presentation'?'Открыть материалы':'Перейти по ссылке'}</small></div><span>›</span></a>)}{!links.length&&<Empty>Добавьте ссылки в настройках.</Empty>}</div></Card><Card title="Фокус недели" action={<small className="green-text">{base.focus.filter((x:any)=>x.done).length} из {base.focus.length}</small>}><div className="focus-list">{base.focus.slice(0,3).map((f:any)=><label key={f.id}><input type="checkbox" checked={f.done} onChange={()=>focusMut.mutate({id:f.id,done:!f.done})}/><span>{f.text}</span></label>)}{!base.focus.length&&<Empty>Фокус недели не задан.</Empty>}</div></Card></div>
 <div className="two-col"><Card title="Задачи команды" action={<Link to="/tasks">Смотреть все →</Link>}><div className="member-tasks">{members.slice(0,2).map((m:Member)=><div className="person-card" key={m.user_id}><div className="person-head"><Avatar name={m.display_name}/><div><b>{m.display_name}</b><small>{roleName[m.role||'cofounder']||'Участник'}</small></div></div><div className="person-numbers"><span><b>{base.tasks.filter((t:Task)=>t.assignee_id===m.user_id).length}</b>Активных</span><span><b>{base.tasks.filter((t:Task)=>t.assignee_id===m.user_id&&t.planned_week===weekStart()).length}</b>На этой неделе</span><span className="red"><b>{base.tasks.filter((t:Task)=>t.assignee_id===m.user_id&&t.blocked).length}</b>Заблокировано</span></div>{base.tasks.filter((t:Task)=>t.assignee_id===m.user_id).slice(0,3).map((t:Task)=><div className="tiny-task" key={t.id}><span>○</span>{t.title}<small>{t.blocked?'!':t.due_date===new Date().toISOString().slice(0,10)?'Сегодня':''}</small></div>)}</div>)}</div></Card><Card title="Дедлайны программ" action={<Link to="/programs">Смотреть все →</Link>}><div className="deadline-table">{base.programs.slice(0,5).map((p:Program)=><Link to={`/programs/${p.id}`} key={p.id}><b>{p.name}</b><span className={p.deadline&&p.deadline<base.today?'late':''}>{ruDate(p.deadline)}</span><Chip tone={p.status==='accepted'?'green':p.status==='rejected'?'red':'gray'}>{statusName[p.status]}</Chip><small>{p.next_step||'Уточнить следующий шаг'}</small></Link>)}</div></Card></div>
 <Card title="Последние решения" action={<Link to="/events">Смотреть все →</Link>}><div className="decision-list">{base.decisions.slice(0,3).map((d:Decision)=><div key={d.id}><span className="decision-icon">▤</span><div><b>{d.title}</b><small>Решение от {ruDate(d.decision_date)}</small></div></div>)}{!base.decisions.length&&<Empty>Решений пока нет.</Empty>}</div></Card>
 <section className="growth-hero"><div><h2>Как растёт Друк</h2><p>Маленькие шаги каждый день превращаются в большие перемены.</p></div><span>Последние 30 дней⌄</span></section><Card title="Ключевые метрики" action={<span className="green-text">Смотреть аналитику →</span>}><div className="metrics-grid"><MetricCard icon="users" value={metric.users_total} label="Пользователей зашло" change={metric.changes?.users_total}/><MetricCard icon="message" value={metric.messages_total} label="Сообщений отправлено" change={metric.changes?.messages_total}/><MetricCard icon="message" value={metric.dialogs_total} label="Новых диалогов" change={metric.changes?.dialogs_total}/><MetricCard icon="users" value={metric.weekly_active} label="Активных пользователей за неделю" change={metric.changes?.weekly_active}/><MetricCard icon="clock" value={formatSeconds(metric.avg_session_seconds)} label="Средняя длина сессии" change={metric.changes?.avg_session_seconds}/><MetricCard icon="chart" value={`${metric.retention_7d||0}%`} label="7-дневное удержание" change={metric.changes?.retention_7d}/><MetricCard icon="users" value={`${metric.registration_conversion||0}%`} label="Конверсия в регистрацию" change={metric.changes?.registration_conversion}/></div></Card>
 <Card title="Обратная связь клиентов" action={<span className="green-text">Смотреть все отзывы →</span>}><div className="feedback-grid">{feedback.length?feedback.slice(0,3).map(f=><article className="feedback" key={f.id}><Chip tone={f.sentiment==='constructive'?'amber':'green'}>{f.sentiment==='constructive'?'Конструктивно':'Положительно'}</Chip><p>«{f.quote}»</p><div><Avatar name={f.author_name}/><span><b>{f.author_name}</b><small>{f.author_role||'Пользователь'}</small></span></div><footer>{(f.tags||[]).map(t=><span key={t}>{t}</span>)}</footer></article>):<Empty>Добавьте первые отзывы через API/интеграцию — они появятся здесь.</Empty>}</div></Card>
 <Card title="💡 Главные инсайты недели"><div className="insights"><Insight n="1" title="Растёт интерес команд" text={metric.registration_conversion?`Конверсия в регистрацию сейчас ${metric.registration_conversion}%.`:'Подключите продуктовые метрики, чтобы видеть динамику.'}/><Insight n="2" title="Пользователи возвращаются" text={metric.retention_7d?`7-дневное удержание — ${metric.retention_7d}%.`:'Удержание появится после загрузки продуктовой аналитики.'}/><Insight n="3" title="Ценят простоту" text={feedback[0]?.quote||'Обратная связь клиентов будет собираться в одном месте.'}/><Insight n="4" title="Просьбы об интеграциях" text="GitHub уже подключается в задачах; следующие интеграции можно вести через настройки."/></div></Card></div>
}
function MetricCard({icon,value,label,change}:{icon:string;value:string|number;label:string;change?:number}){return <div className="metric-card"><div className="metric-top"><span className="metric-icon"><Icon name={icon}/></span><div><b>{typeof value==='number'?value.toLocaleString('ru-RU'):value}</b><small>{label}</small></div>{typeof change==='number'&&<em>↑ +{change}%</em>}</div><svg className="spark" viewBox="0 0 180 36" preserveAspectRatio="none"><polyline points="0,31 15,29 29,31 44,24 60,27 76,18 92,21 108,13 124,17 140,8 156,12 180,2" fill="none" stroke="currentColor" strokeWidth="2"/></svg></div>}
function Insight({n,title,text}:{n:string;title:string;text:string}){return <div className="insight"><span>{n}</span><div><b>{title}</b><p>{text}</p></div></div>}
function formatSeconds(n:number){if(!n)return '0 мин';const m=Math.floor(n/60),s=Math.round(n%60);return `${m} мин ${s} сек`}

function TasksPage(){
 const qc=useQueryClient();const [mine,setMine]=useState(false),[showDone,setShowDone]=useState(false),[view,setView]=useState<'list'|'board'>('list'),[title,setTitle]=useState(''),[description,setDescription]=useState(''),[assignee,setAssignee]=useState(''),[due,setDue]=useState('')
 const q=useQuery<any>({queryKey:['tasks-rich',mine,showDone],queryFn:async()=>{const [tasks,members,issues]=await Promise.all([api(`/tasks?mine=${mine}&include_done=${showDone}`),api('/team'),api('/github/issues')]);return {tasks,members,issues}}})
 const add=useMutation({mutationFn:()=>api('/tasks',json('POST',{title,description:description||null,assignee_id:assignee||null,due_date:due||null,planned_week:weekStart()})),onSuccess:()=>{setTitle('');setDescription('');setDue('');void qc.invalidateQueries({queryKey:['tasks-rich']})}})
 const patch=useMutation({mutationFn:({id,data}:{id:string;data:any})=>api(`/tasks/${id}`,json('PATCH',data)),onSuccess:()=>void qc.invalidateQueries({queryKey:['tasks-rich']})})
 if(q.isLoading)return <Loading/>;if(q.error)return <ErrorBox error={q.error}/>;const {tasks,members,issues}=q.data
 return <><PageTitle title="Задачи" subtitle="Превращаем идеи в реальные результаты." action={<Button onClick={()=>document.getElementById('task-title')?.focus()}><Icon name="plus"/>Новая задача</Button>}/><div className="toolbar"><button className={!mine?'active':''} onClick={()=>setMine(false)}>Все</button><button className={mine?'active':''} onClick={()=>setMine(true)}>Мои</button><button onClick={()=>setShowDone(!showDone)}>{showDone?'Скрыть готовые':'Показывать готовые'}</button><span/><div className="view-toggle"><button className={view==='list'?'active':''} onClick={()=>setView('list')}>☷ Список</button><button className={view==='board'?'active':''} onClick={()=>setView('board')}>▥ Доска</button></div></div><div className="tasks-layout"><div><Card title={<>Задачи <span className="count">{tasks.length+issues.length}</span></>} className="task-list-card">{view==='list'?<div className="task-table"><div className="task-row table-head"><span>Задача</span><span>Исполнитель</span><span>Статус</span><span>Срок</span><span>Неделя</span><span/></div>{tasks.map((t:Task)=><div className="task-row" key={t.id}><input type="checkbox" checked={t.status==='done'} onChange={()=>patch.mutate({id:t.id,data:{status:t.status==='done'?'in_progress':'done'}})}/><div className="task-title-cell"><span className="doc-dot">▤</span><b>{t.title}</b>{t.description&&<small>{t.description}</small>}</div><MemberCell id={t.assignee_id} members={members}/><select className={`status-select ${t.status}`} value={t.status} onChange={e=>patch.mutate({id:t.id,data:{status:e.target.value}})}><option value="planned">Запланировано</option><option value="in_progress">В работе</option><option value="done">Готово</option></select><span>{ruDate(t.due_date)}</span><span>{t.planned_week?`Нед. ${weekNum(t.planned_week)}`:'—'}</span><Dots/></div>)}{issues.map((g:GithubIssue)=><a className="task-row github-row" key={g.id} href={g.url} target="_blank" rel="noreferrer"><span className="github-mark">●</span><div className="task-title-cell"><b>GitHub #{g.number}</b><small>{g.title}</small></div><span>{g.assignee||'—'}</span><Chip tone={g.state==='open'?'green':'purple'}>{g.state==='open'?'Open':'Closed'}</Chip><span>—</span><span>GitHub</span><span>↗</span></a>)}</div>:<TaskBoard tasks={tasks} members={members}/>}</Card>{view==='list'&&<Card title="Доска задач (превью)" action={<button className="text-button" onClick={()=>setView('board')}>Открыть доску →</button>}><TaskBoard tasks={tasks} members={members} preview/></Card>}</div><aside className="right-column"><Card title="Быстрое создание"><form className="stack-form" onSubmit={e=>{e.preventDefault();if(title.trim())add.mutate()}}><label>Название задачи<input id="task-title" value={title} onChange={e=>setTitle(e.target.value)} placeholder="Например: Подготовить презентацию..."/></label><label>Описание (необязательно)<textarea value={description} onChange={e=>setDescription(e.target.value)} placeholder="Краткое описание задачи..." rows={3}/></label><div className="form-two"><label>Исполнитель<select value={assignee} onChange={e=>setAssignee(e.target.value)}><option value="">Не назначен</option>{members.map((m:Member)=><option key={m.user_id} value={m.user_id}>{m.display_name}</option>)}</select></label><label>Срок<input type="date" value={due} onChange={e=>setDue(e.target.value)}/></label></div><Button disabled={!title.trim()||add.isPending}>Создать задачу</Button></form></Card><Card title={<>Заблокированные <span className="red-count">{tasks.filter((x:Task)=>x.blocked).length}</span></>}>{tasks.filter((x:Task)=>x.blocked).slice(0,3).map((t:Task)=><div className="blocked-card" key={t.id}><b>{t.title}</b><small>{t.block_reason||'Нужна помощь команды.'}</small></div>)}{!tasks.some((x:Task)=>x.blocked)&&<Empty>Нет заблокированных задач.</Empty>}</Card><NatureNote text="Нет преград для больших идей"/></aside></div></>
}
function MemberCell({id,members}:{id?:string|null;members:Member[]}){const m=members.find(x=>x.user_id===id);return m?<span className="member-cell"><Avatar name={m.display_name}/>{m.display_name}</span>:<span className="muted">Не назначен</span>}
function TaskBoard({tasks,members,preview}:{tasks:Task[];members:Member[];preview?:boolean}){return <div className={cx('board',preview&&'preview')}>{(['planned','in_progress','done'] as const).map(s=><div className="board-col" key={s}><h3>{statusName[s]} <span>{tasks.filter(t=>t.status===s).length}</span></h3>{tasks.filter(t=>t.status===s).slice(0,preview?4:20).map(t=><div className="board-card" key={t.id}><b>{t.title}</b><div>{t.assignee_id&&<MemberCell id={t.assignee_id} members={members}/>}<small>{t.due_date&&ruDate(t.due_date)}</small></div></div>)}<button>＋ Добавить задачу</button></div>)}</div>}
function weekNum(d:string){const dt=new Date(d+'T12:00:00'),onejan=new Date(dt.getFullYear(),0,1);return Math.ceil((((dt.getTime()-onejan.getTime())/86400000)+onejan.getDay()+1)/7)}

function ProgramsPage(){
 const qc=useQueryClient();const [filter,setFilter]=useState('all'),[name,setName]=useState(''),[deadline,setDeadline]=useState(''),[search,setSearch]=useState('')
 const q=useQuery<any>({queryKey:['programs-rich'],queryFn:async()=>{const [programs,events]=await Promise.all([api('/programs?include_archived=true'),api('/events')]);return {programs,events}}})
 const add=useMutation({mutationFn:()=>api('/programs',json('POST',{name,deadline:deadline||null,status:'considering'})),onSuccess:()=>{setName('');setDeadline('');void qc.invalidateQueries({queryKey:['programs-rich']})}})
 if(q.isLoading)return <Loading/>;if(q.error)return <ErrorBox error={q.error}/>;const programs:Program[]=q.data.programs;const today=new Date().toISOString().slice(0,10);const visible=programs.filter(p=>(filter==='all'||filter==='active'&&!p.archived&&p.status!=='rejected'||filter==='submitted'&&['submitted','next_stage','accepted'].includes(p.status)||filter==='archive'&&p.archived)&&p.name.toLowerCase().includes(search.toLowerCase()))
 const soon=programs.filter(p=>p.deadline).sort((a,b)=>(a.deadline||'').localeCompare(b.deadline||'')).slice(0,4)
 return <><section className="page-banner programs-banner"><div><PageTitle title="Программы" subtitle="Все заявки, дедлайны и следующие шаги — в одном месте."/><div className="toolbar tabs"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>Все <span>{programs.length}</span></button><button className={filter==='active'?'active':''} onClick={()=>setFilter('active')}>Активные <span>{programs.filter(p=>!p.archived&&p.status!=='rejected').length}</span></button><button className={filter==='submitted'?'active':''} onClick={()=>setFilter('submitted')}>Подали <span>{programs.filter(p=>['submitted','next_stage','accepted'].includes(p.status)).length}</span></button><button className={filter==='archive'?'active':''} onClick={()=>setFilter('archive')}>Архив <span>{programs.filter(p=>p.archived).length}</span></button></div></div><div className="banner-side" style={{backgroundImage:`url(${asset('hero-programs.webp')})`}}><Button onClick={()=>document.getElementById('new-program')?.focus()}><Icon name="plus"/>Новая программа</Button></div></section><div className="program-layout"><div><div className="summary-cards"><Summary value={programs.filter(p=>!p.archived).length} label="Активные программы"/><Summary value={programs.filter(p=>p.deadline&&p.deadline>=today&&daysTo(p.deadline)<=7).length} label="Дедлайны на 7 дней" tone="red"/><Summary value={programs.filter(p=>['submitted','next_stage'].includes(p.status)).length} label="Подали заявки"/><Summary value={programs.filter(p=>p.status==='accepted').length} label="Приняты"/></div><Card title="Ближайшие дедлайны" action={<span className="green-text">Смотреть все →</span>}><div className="deadline-cards">{soon.map(p=><Link to={`/programs/${p.id}`} key={p.id} className={cx('deadline-card',p.deadline&&p.deadline<today&&'overdue')}><span className="date-icon"><Icon name="calendar"/></span><b>{ruDate(p.deadline)}</b><Chip tone={p.deadline&&p.deadline<today?'red':'amber'}>{p.deadline&&p.deadline<today?'Просрочен':daysTo(p.deadline)===0?'Сегодня':`Через ${daysTo(p.deadline)} дн.`}</Chip><h3>{p.name}</h3><small>{p.next_step||'Следующий шаг не указан'}</small></Link>)}</div></Card><Card title={<>Все программы <span className="count">{visible.length}</span></>} action={<input className="inline-search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Поиск по программам..."/>}><div className="program-table"><div className="program-row ph"><span>Название программы</span><span>Дедлайн</span><span>Статус</span><span>Следующий шаг</span><span/></div>{visible.map(p=><Link to={`/programs/${p.id}`} className="program-row" key={p.id}><span className="program-name"><i>↗</i><b>{p.name}</b><small>{p.archived?'Архив':'Акселератор / программа'}</small></span><span>{ruDate(p.deadline)}</span><Chip tone={p.status==='accepted'?'green':p.status==='rejected'?'red':p.status==='submitted'?'blue':'gray'}>{statusName[p.status]}</Chip><span>{p.next_step||'Уточнить следующий шаг'}</span><span>⋮</span></Link>)}</div></Card><Card title="Быстро добавить программу"><form className="inline-form" onSubmit={e=>{e.preventDefault();if(name.trim())add.mutate()}}><input id="new-program" value={name} onChange={e=>setName(e.target.value)} placeholder="Название программы"/><input type="date" value={deadline} onChange={e=>setDeadline(e.target.value)}/><Button disabled={!name.trim()}>Добавить</Button></form></Card></div><aside className="right-column"><MiniCalendar items={programs.map(p=>({date:p.deadline,label:p.name}))}/><Card title="Ближайшие события">{q.data.events.filter((e:EventRow)=>e.meeting_date>=today).slice(0,4).map((e:EventRow)=><div className="event-mini" key={e.id}><span>{ruDate(e.meeting_date)}</span><b>{e.title}</b><small>{eventNames[e.event_type||'meeting']}</small></div>)}</Card><NatureNote text="Идеи сегодня — большие результаты завтра"/></aside></div></>
}
function Summary({value,label,tone}:{value:number;label:string;tone?:string}){return <div className={`summary ${tone||''}`}><span><Icon name={tone==='red'?'calendar':'programs'}/></span><div><b>{value}</b><small>{label}</small></div></div>}
function daysTo(d?:string|null){if(!d)return 999;return Math.ceil((new Date(d+'T12:00:00').getTime()-new Date(new Date().toISOString().slice(0,10)+'T12:00:00').getTime())/86400000)}
function MiniCalendar({items}:{items:Array<{date?:string|null;label?:string}>}){const now=new Date(),year=now.getFullYear(),month=now.getMonth(),first=new Date(year,month,1),days=new Date(year,month+1,0).getDate(),offset=(first.getDay()+6)%7;const marked=new Set(items.filter(x=>x.date?.startsWith(`${year}-${String(month+1).padStart(2,'0')}`)).map(x=>Number(x.date!.slice(-2))));return <Card title={now.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}><div className="calendar"><div className="weekdays">{['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=><span key={x}>{x}</span>)}</div><div className="days">{Array.from({length:offset}).map((_,i)=><span key={`e${i}`}/>) }{Array.from({length:days},(_,i)=>i+1).map(d=><span key={d} className={cx(d===now.getDate()&&'today',marked.has(d)&&'marked')}>{d}</span>)}</div></div></Card>}

function ProgramPage(){
 const {id}=useParams();const qc=useQueryClient();const [editing,setEditing]=useState(false),[draft,setDraft]=useState<any>({});const [newCheck,setNewCheck]=useState(''),[question,setQuestion]=useState(''),[answer,setAnswer]=useState(''),[libOpen,setLibOpen]=useState(false),[answersEditing,setAnswersEditing]=useState(false),[answerDrafts,setAnswerDrafts]=useState<Record<string,{question:string;answer:string}>>({})
 const q=useQuery<any>({queryKey:['program-detail-rich',id],enabled:Boolean(id),queryFn:async()=>{const [detail,library,projectFiles]=await Promise.all([api(`/programs/${id}`),api('/answers'),api('/files')]);return {detail,library,projectFiles}}})
 const patch=useMutation({mutationFn:(data:any)=>api(`/programs/${id}`,json('PATCH',data)),onSuccess:()=>{setEditing(false);void qc.invalidateQueries({queryKey:['program-detail-rich',id]});void qc.invalidateQueries({queryKey:['programs-rich']})}})
 const addCheck=useMutation({mutationFn:()=>api(`/programs/${id}/checklist`,json('POST',{text:newCheck})),onSuccess:()=>{setNewCheck('');void qc.invalidateQueries({queryKey:['program-detail-rich',id]})}})
 const check=useMutation({mutationFn:({cid,done}:{cid:string;done:boolean})=>api(`/checklist/${cid}`,json('PATCH',{done})),onSuccess:()=>void qc.invalidateQueries({queryKey:['program-detail-rich',id]})})
 const addAnswer=useMutation({mutationFn:()=>api(`/programs/${id}/answers`,json('POST',{question,answer})),onSuccess:()=>{setQuestion('');setAnswer('');void qc.invalidateQueries({queryKey:['program-detail-rich',id]})}})
 const fromLib=useMutation({mutationFn:(answer_id:string)=>api(`/programs/${id}/answers/from-library`,json('POST',{answer_id})),onSuccess:()=>{setLibOpen(false);void qc.invalidateQueries({queryKey:['program-detail-rich',id]})}})
 const snap=useMutation({mutationFn:()=>api(`/programs/${id}/submissions`,json('POST')),onSuccess:()=>void qc.invalidateQueries({queryKey:['program-detail-rich',id]})})
 const upload=useMutation({mutationFn:async(file:File)=>{const fd=new FormData();fd.append('file',file);fd.append('scope','program');fd.append('program_id',id!);return api('/files',{method:'POST',body:fd})},onSuccess:()=>void qc.invalidateQueries({queryKey:['program-detail-rich',id]})})
 const linkFile=useMutation({mutationFn:(file_id:string)=>api(`/programs/${id}/files/link`,json('POST',{file_id})),onSuccess:()=>void qc.invalidateQueries({queryKey:['program-detail-rich',id]})})
 const saveAnswers=useMutation({mutationFn:()=>Promise.all(Object.entries(answerDrafts).map(([aid,value])=>api(`/program-answers/${aid}`,json('PATCH',value)))),onSuccess:()=>{setAnswersEditing(false);void qc.invalidateQueries({queryKey:['program-detail-rich',id]})}})
 if(q.isLoading)return <Loading/>;if(q.error)return <ErrorBox error={q.error}/>;const d:ProgramDetail=q.data.detail,p=d.program;const completed=d.checklist.filter(x=>x.done).length
 return <><div className="breadcrumbs"><Link to="/programs">Программы</Link><span>/</span><b>{p.name}</b></div><div className="program-head"><div><div className="title-line"><h1>{p.name}</h1><Chip>{statusName[p.status]}</Chip></div><p>{p.notes||'Акселерационная программа для технологических команд'}</p></div><div className="program-meta"><div><Icon name="calendar"/><span>Дедлайн<b>{ruDate(p.deadline)}</b></span></div><div><Icon name="chart"/><span>Следующий шаг<b>{p.next_step||'Не указан'}</b></span></div>{p.url&&<a className="btn secondary" href={p.url} target="_blank" rel="noreferrer">Открыть на сайте ↗</a>}</div></div><div className="program-detail-grid"><div><Card title="О программе" action={<button className="icon-btn" onClick={()=>{setDraft(p);setEditing(!editing)}}><Icon name="edit"/></button>}>{editing?<form className="edit-grid" onSubmit={e=>{e.preventDefault();patch.mutate(draft)}}><label>Название<input value={draft.name||''} onChange={e=>setDraft({...draft,name:e.target.value})}/></label><label>Дедлайн<input type="date" value={draft.deadline||''} onChange={e=>setDraft({...draft,deadline:e.target.value||null})}/></label><label>Статус<select value={draft.status||'considering'} onChange={e=>setDraft({...draft,status:e.target.value})}>{Object.entries(statusName).filter(([k])=>!['planned','in_progress','done'].includes(k)).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>Следующий шаг<input value={draft.next_step||''} onChange={e=>setDraft({...draft,next_step:e.target.value})}/></label><label className="full">Заметки<textarea rows={3} value={draft.notes||''} onChange={e=>setDraft({...draft,notes:e.target.value})}/></label><div className="full form-actions"><Button>Сохранить</Button><Button type="button" kind="secondary" onClick={()=>setEditing(false)}>Отмена</Button></div></form>:<div className="program-info"><span>Название<b>{p.name}</b></span><span>Дедлайн<b>{ruDate(p.deadline)}</b></span><span>Статус<Chip>{statusName[p.status]}</Chip></span><span>Следующий шаг<b>{p.next_step||'—'}</b></span><span className="wide">Заметки<b>{p.notes||'—'}</b></span></div>}</Card><div className="two-col equal"><Card title="Чек-лист" action={<div className="progress-wrap"><div><i style={{width:`${d.checklist.length?completed/d.checklist.length*100:0}%`}}/></div><span>{completed} из {d.checklist.length}</span></div>}><div className="checklist">{d.checklist.map(c=><label key={c.id}><input type="checkbox" checked={c.done} onChange={()=>check.mutate({cid:c.id,done:!c.done})}/><span>{c.text}</span><small>{c.done?'Готово':'—'}</small></label>)}<form className="inline-form" onSubmit={e=>{e.preventDefault();if(newCheck.trim())addCheck.mutate()}}><input value={newCheck} onChange={e=>setNewCheck(e.target.value)} placeholder="Добавить пункт..."/><Button>＋</Button></form></div></Card><Card title="Документы" action={<label className="btn primary file-label">＋ Добавить<input type="file" hidden onChange={e=>e.target.files?.[0]&&upload.mutate(e.target.files[0])}/></label>}><div className="doc-list">{d.files.map(l=><FileLine key={l.id} file={l.files}/>)}{!d.files.length&&<Empty>Файлов программы пока нет.</Empty>}</div><div className="link-existing"><select defaultValue="" onChange={e=>{if(e.target.value)linkFile.mutate(e.target.value);e.target.value=''}}><option value="">🔗 Привязать файл из общего хранилища</option>{(q.data.projectFiles as FileRow[]).filter(f=>!d.files.some(x=>x.file_id===f.id)).map(f=><option key={f.id} value={f.id}>{f.display_name}</option>)}</select></div></Card></div><Card title="Ответы для заявки" action={<div className="answer-tools"><button className="text-button" onClick={()=>setLibOpen(!libOpen)}>Найти в базе</button><button className="text-button" onClick={()=>{if(answersEditing){saveAnswers.mutate()}else{setAnswerDrafts(Object.fromEntries(d.answers.map(a=>[a.id,{question:a.question,answer:a.answer}])));setAnswersEditing(true)}}} disabled={saveAnswers.isPending}>{answersEditing?(saveAnswers.isPending?'Сохраняем…':'Сохранить все'):'Редактировать все'}</button>{answersEditing&&<button className="text-button muted-action" onClick={()=>setAnswersEditing(false)}>Отмена</button>}</div>}>{libOpen&&<div className="library-picker">{(q.data.library as Answer[]).slice(0,8).map(a=><button key={a.id} onClick={()=>fromLib.mutate(a.id)}><b>{a.question}</b><small>{a.answer.slice(0,100)}…</small></button>)}</div>}<form className="program-answer-form" onSubmit={e=>{e.preventDefault();if(question.trim())addAnswer.mutate()}}><input value={question} onChange={e=>setQuestion(e.target.value)} placeholder="Вопрос из заявки"/><textarea value={answer} onChange={e=>setAnswer(e.target.value)} rows={4} placeholder="Ответ"/><div><Button disabled={!question.trim()}>Добавить ответ</Button></div></form><div className="program-answers">{d.answers.map((a,i)=><article key={a.id} className={answersEditing?'editing-answer':''}><div>{answersEditing?<input className="program-answer-question" value={answerDrafts[a.id]?.question??a.question} onChange={e=>setAnswerDrafts({...answerDrafts,[a.id]:{question:e.target.value,answer:answerDrafts[a.id]?.answer??a.answer}})}/>:<b>{i+1}. {a.question}</b>}{a.source_answer_id&&<Chip>Из базы ответов</Chip>}</div>{answersEditing?<textarea className="program-answer-editor" rows={6} value={answerDrafts[a.id]?.answer??a.answer} onChange={e=>setAnswerDrafts({...answerDrafts,[a.id]:{question:answerDrafts[a.id]?.question??a.question,answer:e.target.value}})}/>:<p>{a.answer||'Ответ пока пуст.'}</p>}<footer><button onClick={()=>void navigator.clipboard.writeText(answersEditing?(answerDrafts[a.id]?.answer??a.answer):a.answer)}><Icon name="copy"/>Копировать</button>{!answersEditing&&<button onClick={()=>{setAnswerDrafts(Object.fromEntries(d.answers.map(x=>[x.id,{question:x.question,answer:x.answer}])));setAnswersEditing(true)}}>✎ Адаптировать</button>}</footer><CommentsPanel entityType="program_answer" entityId={a.id} compact/></article>)}</div></Card></div><aside className="right-column"><NatureNote text="Планомерные шаги приводят к большим результатам" image="hero-settings.webp"/><Card title="Отправленная версия"><p className="muted">Зафиксируйте финальную версию заявки после отправки, чтобы сохранить историю.</p><Button onClick={()=>snap.mutate()} disabled={snap.isPending}>▤ Зафиксировать версию</Button><h3 className="subhead">История отправок</h3>{d.submissions.map(s=><div className="submission" key={s.id}><b>Версия от {new Date(s.created_at).toLocaleDateString('ru-RU')}</b><small>{new Date(s.created_at).toLocaleString('ru-RU')}</small></div>)}</Card><Card title="Дополнительно"><button className="menu-action" onClick={()=>{setDraft(p);setEditing(true)}}>✎ Редактировать заметки</button><button className="menu-action" onClick={()=>patch.mutate({archived:!p.archived})}>▣ {p.archived?'Вернуть из архива':'Архивировать программу'}</button><button className="menu-action">↗ Поделиться</button><button className="menu-action danger-text" onClick={()=>{if(confirm('Удалить программу?'))void api(`/programs/${id}`,{method:'DELETE'}).then(()=>window.location.hash='#/programs')}}>⌫ Удалить из списка</button></Card></aside></div></>
}
function FileLine({file}:{file:FileRow}){const [open,setOpen]=useState(false);return <div className="file-line-wrap"><div className="file-line"><span className={`file-type ${file.original_name.split('.').pop()?.toLowerCase()}`}>{(file.original_name.split('.').pop()||'FILE').toUpperCase().slice(0,4)}</span><div><b>{file.display_name}</b><small>{file.scope==='program'?'Документ программы':'Общий файл'} · {bytes(file.size_bytes)}</small></div><span>{new Date(file.created_at).toLocaleDateString('ru-RU')}</span><button className="icon-btn file-comment-btn" title="Комментарии" onClick={()=>setOpen(!open)}>💬</button></div>{open&&<CommentsPanel entityType="file" entityId={file.id} compact/>}</div>}

function EventsPage(){
 const qc=useQueryClient();const [type,setType]=useState('all'),[title,setTitle]=useState(''),[eventType,setEventType]=useState('meeting'),[date,setDate]=useState(new Date().toISOString().slice(0,10)),[time,setTime]=useState('10:00'),[mode,setMode]=useState('online'),[program,setProgram]=useState('')
 const q=useQuery<any>({queryKey:['events-rich'],queryFn:async()=>{const [events,programs,members]=await Promise.all([api('/events'),api('/programs'),api('/team')]);return {events,programs,members}}})
 const add=useMutation({mutationFn:()=>api('/events',json('POST',{title,event_type:eventType,meeting_date:date,start_time:time,mode,program_id:program||null,notes:''})),onSuccess:()=>{setTitle('');void qc.invalidateQueries({queryKey:['events-rich']})}})
 if(q.isLoading)return <Loading/>;if(q.error)return <ErrorBox error={q.error}/>;const events:EventRow[]=q.data.events;const today=new Date().toISOString().slice(0,10);const visible=events.filter(e=>type==='all'||e.event_type===type);const upcoming=visible.filter(e=>e.meeting_date>=today).sort((a,b)=>(a.meeting_date+(a.start_time||'')).localeCompare(b.meeting_date+(b.start_time||'')));const past=visible.filter(e=>e.meeting_date<today).slice(0,6)
 return <><section className="page-banner events-banner"><div><PageTitle title="Мероприятия" subtitle="Видим всё, что предстоит команде: события, встречи и внешние активности."/><div className="toolbar tabs event-tabs">{[['all','Все'],['meeting','Встречи'],['interview','Интервью'],['demo','Демо-дни'],['pitch','Питчи'],['webinar','Вебинары'],['deadline','Важные даты']].map(([k,l])=><button key={k} className={type===k?'active':''} onClick={()=>setType(k)}>{l}</button>)}</div></div><div className="banner-side" style={{backgroundImage:`url(${asset('hero-events.webp')})`}}><Button onClick={()=>document.getElementById('event-title')?.focus()}><Icon name="plus"/>Создать мероприятие</Button></div></section><div className="events-layout"><div><Card title={<>Ближайшие мероприятия <span className="count">{upcoming.length}</span></>} action={<span className="green-text">Смотреть все →</span>}><div className="event-list">{groupEvents(upcoming).map(([day,rows])=><div className="event-day" key={day}><h3>{dayLabel(day)}</h3>{rows.map(e=><div className="event-row" key={e.id}><span className="event-check">□</span><span className="event-time">{(e.start_time||'').slice(0,5)}{e.end_time&&` – ${e.end_time.slice(0,5)}`}</span><div><b>{e.title}</b><small>{e.notes||'Без описания'}</small></div><Chip tone={eventTone(e.event_type||'meeting')}>{eventNames[e.event_type||'meeting']}</Chip><span>{e.mode==='online'?'▣ Онлайн':e.location||'Офис'}</span><span>{programName(e.program_id,q.data.programs)}</span><div className="avatar-stack">{(e.participants||[]).slice(0,3).map(pid=><MemberAvatar key={pid} id={pid} members={q.data.members}/>)}</div><Dots/></div>)}</div>)}</div></Card><Card title="Прошедшие мероприятия" action={<span className="green-text">Смотреть все →</span>}><div className="past-events">{past.map(e=><article key={e.id}><small>{ruDate(e.meeting_date)}</small><b>{e.title}</b><span>{programName(e.program_id,q.data.programs)||eventNames[e.event_type||'meeting']}</span><Chip tone={eventTone(e.event_type||'meeting')}>{eventNames[e.event_type||'meeting']}</Chip><p>{e.notes||'Итоги мероприятия можно записать в заметки.'}</p></article>)}{!past.length&&<Empty>Прошедших мероприятий пока нет.</Empty>}</div></Card></div><aside className="right-column"><MiniCalendar items={events.map(e=>({date:e.meeting_date,label:e.title}))}/><Card title="Быстрое создание"><form className="stack-form" onSubmit={e=>{e.preventDefault();if(title.trim())add.mutate()}}><input id="event-title" value={title} onChange={e=>setTitle(e.target.value)} placeholder="Название мероприятия..."/><select value={eventType} onChange={e=>setEventType(e.target.value)}>{Object.entries(eventNames).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><div className="form-two"><input type="date" value={date} onChange={e=>setDate(e.target.value)}/><input type="time" value={time} onChange={e=>setTime(e.target.value)}/></div><select value={mode} onChange={e=>setMode(e.target.value)}><option value="online">Онлайн</option><option value="offline">Офлайн</option></select><select value={program} onChange={e=>setProgram(e.target.value)}><option value="">Без привязки к программе</option>{q.data.programs.map((p:Program)=><option key={p.id} value={p.id}>{p.name}</option>)}</select><Button disabled={!title.trim()}>Создать мероприятие</Button></form></Card><NatureNote text="Каждое событие приближает к большим делам"/></aside></div></>
}
function groupEvents(events:EventRow[]){const m=new Map<string,EventRow[]>();events.forEach(e=>m.set(e.meeting_date,[...(m.get(e.meeting_date)||[]),e]));return [...m.entries()]}
function dayLabel(d:string){const today=new Date().toISOString().slice(0,10),tom=new Date(Date.now()+86400000).toISOString().slice(0,10);return `${d===today?'Сегодня':d===tom?'Завтра':new Date(d+'T12:00').toLocaleDateString('ru-RU',{weekday:'long'})}, ${ruDate(d)}`}
function eventTone(t:string){return t==='pitch'||t==='deadline'?'red':t==='interview'?'blue':t==='webinar'?'purple':t==='external'?'amber':'green'}
function programName(id:string|null|undefined,programs:Program[]){return programs.find(p=>p.id===id)?.name||''}
function MemberAvatar({id,members}:{id:string;members:Member[]}){const m=members.find(x=>x.user_id===id);return <Avatar name={m?.display_name||'У'}/>}

function FilesPage(){
 const qc=useQueryClient();const [filter,setFilter]=useState('all'),[search,setSearch]=useState(''),[commentFile,setCommentFile]=useState<string|null>(null);const q=useQuery<any>({queryKey:['files-rich'],queryFn:async()=>{const [files,settings,programs]=await Promise.all([api('/files'),api('/settings'),api('/programs')]);return {files,settings,programs}}})
 const upload=useMutation({mutationFn:async(file:File)=>{const fd=new FormData();fd.append('file',file);fd.append('scope','project');return api('/files',{method:'POST',body:fd})},onSuccess:()=>void qc.invalidateQueries({queryKey:['files-rich']})})
 const del=useMutation({mutationFn:(id:string)=>api(`/files/${id}`,{method:'DELETE'}),onSuccess:()=>void qc.invalidateQueries({queryKey:['files-rich']})})
 const setPresentation=useMutation({mutationFn:(id:string)=>api('/settings',json('PATCH',{presentation_file_id:id})),onSuccess:()=>void qc.invalidateQueries({queryKey:['files-rich']})})
 const rename=useMutation({mutationFn:({id,name}:{id:string;name:string})=>api(`/files/${id}`,json('PATCH',{display_name:name})),onSuccess:()=>void qc.invalidateQueries({queryKey:['files-rich']})})
 async function openFile(id:string){const x:any=await api(`/files/${id}/signed-url`,json('POST'));window.open(x.url,'_blank','noopener,noreferrer')}
 if(q.isLoading)return <Loading/>;if(q.error)return <ErrorBox error={q.error}/>;const files:FileRow[]=q.data.files;const settings:Settings=q.data.settings||{};const visible=files.filter(f=>(filter==='all'||filter==='project'&&f.scope==='project'||filter==='program'&&f.scope==='program')&&f.display_name.toLowerCase().includes(search.toLowerCase()));const presentation=files.find(f=>f.id===settings.presentation_file_id)
 return <><PageTitle title="Файлы" subtitle="Все важные материалы в одном месте. Храните, делитесь, используйте в проектах." action={<label className="btn primary file-label">⇧ Загрузить файл<input type="file" hidden onChange={e=>e.target.files?.[0]&&upload.mutate(e.target.files[0])}/></label>}/><div className="files-layout"><div><Card className="presentation-card">{presentation?<><span className="overline green">ВЫБРАНА КАК ПРЕЗЕНТАЦИЯ</span><h2>Актуальная презентация</h2><div className="presentation-file"><span className="file-type pptx">P</span><div><b>{presentation.display_name}</b><small>PPTX · {bytes(presentation.size_bytes)} · Обновлён {new Date(presentation.created_at).toLocaleDateString('ru-RU')}</small></div><Button kind="secondary" onClick={()=>void openFile(presentation.id)}>Открыть ↗</Button></div></>:<><h2>Актуальная презентация</h2><p className="muted">Выберите презентацию из списка файлов через меню действий.</p></>}<div className="presentation-art" style={{backgroundImage:`url(${asset('hero-files.webp')})`}}/></Card><Card title={<>Все файлы <span className="count">{visible.length}</span></>} action={<><select className="compact-select" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Все файлы</option><option value="project">Общие файлы</option><option value="program">Файлы программ</option></select><input className="inline-search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Поиск..."/></>}><div className="files-table"><div className="file-row ph"><span>Название</span><span>Тип</span><span>Размер</span><span>Дата загрузки</span><span>Связь</span><span>Действия</span></div>{visible.map(f=><div className="file-row" key={f.id}><div className="file-name"><span className={`file-type ${f.original_name.split('.').pop()}`}>{(f.original_name.split('.').pop()||'F').slice(0,1).toUpperCase()}</span><b>{f.display_name}</b></div><Chip tone="gray">{(f.original_name.split('.').pop()||'FILE').toUpperCase()}</Chip><span>{bytes(f.size_bytes)}</span><span>{new Date(f.created_at).toLocaleDateString('ru-RU')}</span><Chip tone={f.scope==='program'?'blue':'green'}>{f.scope==='program'?'Программа':'Общий'}</Chip><span className="file-actions"><button onClick={()=>void openFile(f.id)}>↗</button><button onClick={()=>{const n=prompt('Новое название',f.display_name);if(n)rename.mutate({id:f.id,name:n})}}>✎</button><button title="Комментарии" onClick={()=>setCommentFile(commentFile===f.id?null:f.id)}>💬</button><button title="Сделать презентацией" onClick={()=>setPresentation.mutate(f.id)}>★</button><button onClick={()=>{if(confirm('Удалить файл?'))del.mutate(f.id)}}>⋮</button></span></div>)}</div></Card><div className="tip">💡 <b>Совет</b><span>Прикрепляйте общие файлы к программам — один файл, много контекстов.</span></div></div><aside className="right-column">{commentFile&&<Card title={<>Комментарии · <span className="comment-file-title">{files.find(f=>f.id===commentFile)?.display_name}</span></>}><CommentsPanel entityType="file" entityId={commentFile}/></Card>}<Card title="Загрузить файлы"><label className="dropzone"><span>⇧</span><b>Перетащите файлы сюда<br/>или нажмите для выбора</b><input type="file" hidden onChange={e=>e.target.files?.[0]&&upload.mutate(e.target.files[0])}/></label><div className="limits"><b>Ограничения</b><span>Размер файла — до 20 МБ</span><span>Поддерживаемые форматы: PDF, DOCX, XLSX, PPTX, PNG, JPG, TXT</span></div></Card><Card title="Недавние файлы">{files.slice(0,5).map(f=><button className="recent-file" key={f.id} onClick={()=>void openFile(f.id)}><span className={`file-type ${f.original_name.split('.').pop()}`}>{(f.original_name.split('.').pop()||'F')[0].toUpperCase()}</span><span><b>{f.display_name}</b><small>{new Date(f.created_at).toLocaleDateString('ru-RU')}</small></span></button>)}</Card><NatureNote text="Хорошие материалы ускоряют большие дела"/></aside></div></>
}

function AnswersPage(){
 const qc=useQueryClient();const [search,setSearch]=useState(''),[selected,setSelected]=useState<string|null>(null),[editing,setEditing]=useState(false),[draft,setDraft]=useState({question:'',answer:'',keywords:''}),[newOpen,setNewOpen]=useState(false)
 const q=useQuery<any>({queryKey:['answers-rich',search],queryFn:async()=>{const [answers,programs]=await Promise.all([api(`/answers${search.trim()?`?q=${encodeURIComponent(search.trim())}`:''}`),api('/programs')]);return {answers,programs}}})
 const save=useMutation({mutationFn:()=>selected?api(`/answers/${selected}`,json('PATCH',draft)):api('/answers',json('POST',draft)),onSuccess:()=>{setEditing(false);setNewOpen(false);void qc.invalidateQueries({queryKey:['answers-rich']})}})
 if(q.isLoading)return <Loading/>;if(q.error)return <ErrorBox error={q.error}/>;const answers:Answer[]=q.data.answers;const current=answers.find(a=>a.id===selected)||answers[0];const topics=topicCounts(answers)
 return <><section className="page-banner answers-banner"><div><PageTitle title="База ответов" subtitle="Переиспользуем ответы на вопросы из заявок. Сохраняем экспертизу. Отвечаем быстрее. Делаем больше." action={<Button onClick={()=>{setDraft({question:'',answer:'',keywords:''});setSelected(null);setNewOpen(true);setEditing(true)}}><Icon name="plus"/>Новый ответ</Button>}/><div className="big-search"><Icon name="search"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Поиск по вопросу, ответу или ключевым словам..."/></div></div><div className="banner-side" style={{backgroundImage:`url(${asset('hero-answers.webp')})`}}/></section><div className="answers-layout"><aside className="topics"><h3>Темы</h3><button className="active">Все ответы <span>{answers.length}</span></button>{topics.map(([t,n])=><button key={t}>{t}<span>{n}</span></button>)}<hr/><h3>Сохранённые подборки</h3>{['Часто используемые','Для акселераторов','Для инвесторов','Demo Day','Мои черновики'].map(x=><button key={x}>▱ {x}</button>)}</aside><section className="answer-list"><div className="list-head"><h2>Все ответы <span>({answers.length})</span></h2><select><option>По дате обновления</option></select></div>{answers.map(a=><button className={cx('answer-card',current?.id===a.id&&'selected')} key={a.id} onClick={()=>{setSelected(a.id);setEditing(false)}}><b>{a.question}</b><p>{a.answer.slice(0,155)}{a.answer.length>155?'…':''}</p><footer>{keywordList(a.keywords).slice(0,5).map((k,i)=><Chip key={k} tone={i===0?'green':'gray'}>{k}</Chip>)}<small>Обновлено {new Date(a.updated_at).toLocaleDateString('ru-RU')}</small><small>{a.answer.length} знаков</small></footer></button>)}</section><section className="answer-detail">{(current||newOpen)?<AnswerDetail answer={newOpen?draft:current!} editing={editing} draft={draft} setDraft={setDraft} onEdit={()=>{if(current){setDraft({question:current.question,answer:current.answer,keywords:current.keywords});setEditing(true)}}} onSave={()=>save.mutate()} programs={q.data.programs}/>:<Empty>Выберите ответ слева.</Empty>}</section></div></>
}
function topicCounts(answers:Answer[]){const labels=['Проблема','ЦА','Отличия','Команда','Бизнес-модель','Стадия','Планы'];return labels.map(l=>[l,answers.filter(a=>(a.keywords+a.question).toLowerCase().includes(l.toLowerCase())).length] as [string,number]).filter(x=>x[1]>0)}
function keywordList(k:string){return k.split(/[,;#]/).map(x=>x.trim()).filter(Boolean)}
function AnswerDetail({answer,editing,draft,setDraft,onEdit,onSave,programs}:{answer:Answer|{question:string;answer:string;keywords:string};editing:boolean;draft:any;setDraft:(x:any)=>void;onEdit:()=>void;onSave:()=>void;programs:Program[]}){const [program,setProgram]=useState('');async function addToProgram(){if(!program||!('id' in answer))return;await api(`/programs/${program}/answers/from-library`,json('POST',{answer_id:answer.id}));alert('Ответ добавлен в программу')}return <><div className="detail-head"><h2>{editing?<input value={draft.question} onChange={e=>setDraft({...draft,question:e.target.value})}/>:answer.question}</h2><Dots/></div><Chip>Проблема</Chip><h3>Ответ</h3>{editing?<textarea className="answer-editor" rows={13} value={draft.answer} onChange={e=>setDraft({...draft,answer:e.target.value})}/>:<div className="answer-body">{answer.answer}</div>}<small className="counter">{(editing?draft.answer:answer.answer).length} / 2000 знаков</small><div className="keywords"><h3>Ключевые слова</h3>{editing?<input value={draft.keywords} onChange={e=>setDraft({...draft,keywords:e.target.value})} placeholder="проблема, образование, доступность"/>:<div>{keywordList(answer.keywords).map(k=><Chip key={k} tone="gray">{k}</Chip>)}</div>}</div><div className="use-program"><h3>Использовать в программе</h3><select value={program} onChange={e=>setProgram(e.target.value)}><option value="">Выберите программу...</option>{programs.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></div><div className="detail-actions">{editing?<Button onClick={onSave}>Сохранить</Button>:<><Button kind="secondary" onClick={()=>void navigator.clipboard.writeText(answer.answer)}><Icon name="copy"/>Копировать</Button><Button kind="secondary" onClick={onEdit}><Icon name="edit"/>Изменить</Button><Button disabled={!program} onClick={()=>void addToProgram()}>➤ Использовать в программе</Button></>}</div>{('id' in answer)&&<CommentsPanel entityType="answer" entityId={answer.id}/>}</>}

function SettingsPage(){
 const qc=useQueryClient();const q=useQuery<any>({queryKey:['settings-rich'],queryFn:async()=>{const [settings,members,links,repos,invites]=await Promise.all([api('/settings'),api('/team'),api('/links'),api('/github/repositories'),api('/invites')]);return {settings,members,links,repos,invites}}});const [form,setForm]=useState<any>(null),[invite,setInvite]=useState({email:'',display_name:'',role:'member'}),[repo,setRepo]=useState('')
 useEffect(()=>{if(q.data?.settings&&!form)setForm(q.data.settings)},[q.data,form])
 const save=useMutation({mutationFn:()=>api('/settings',json('PATCH',form)),onSuccess:()=>void qc.invalidateQueries({queryKey:['settings-rich']})})
 const inviteMut=useMutation({mutationFn:()=>api('/invites',json('POST',invite)),onSuccess:()=>{setInvite({email:'',display_name:'',role:'member'});void qc.invalidateQueries({queryKey:['settings-rich']})}})
 const addRepo=useMutation({mutationFn:()=>api('/github/repositories',json('POST',{full_name:repo})),onSuccess:()=>{setRepo('');void qc.invalidateQueries({queryKey:['settings-rich']})}})
 const sync=useMutation({mutationFn:(id:string)=>api(`/github/repositories/${id}/sync`,json('POST')),onSuccess:()=>void qc.invalidateQueries({queryKey:['settings-rich']})})
 if(q.isLoading||!form)return <Loading/>;if(q.error)return <ErrorBox error={q.error}/>;const links:QuickLink[]=q.data.links
 return <><section className="settings-banner"><PageTitle title="Настройки" subtitle="Настройте проект, ссылки, участников и интеграции."/><div style={{backgroundImage:`url(${asset('hero-settings.webp')})`}}/></section><div className="settings-grid"><Card title="О проекте" action={<Button kind="secondary" onClick={()=>save.mutate()}><Icon name="edit"/>Сохранить изменения</Button>}><div className="stack-form"><label>Название проекта<input value={form.project_name||''} onChange={e=>setForm({...form,project_name:e.target.value})}/></label><label>Краткое описание<textarea rows={4} maxLength={500} value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/><small className="counter">{(form.description||'').length} / 500</small></label><div className="form-two"><label>Этап<input value={form.stage||''} onChange={e=>setForm({...form,stage:e.target.value})}/></label><label>Следующий результат<input value={form.next_result||''} onChange={e=>setForm({...form,next_result:e.target.value})}/></label></div></div></Card><Card title="Быстрые ссылки" action={<span className="muted">Редактируются прямо здесь</span>}><div className="settings-links">{['landing','telegram','presentation'].map(kind=>{const l=links.find(x=>x.kind===kind);return <QuickLinkEditor key={kind} kind={kind} link={l} onDone={()=>void qc.invalidateQueries({queryKey:['settings-rich']})}/>})}</div></Card><Card title="Участники проекта" className="span-2"><div className="members-settings"><div className="member-list">{q.data.members.map((m:Member)=><div className="member-setting" key={m.user_id}><Avatar name={m.display_name}/><div><b>{m.display_name}</b><small>{m.user_id.slice(0,8)}…</small></div><Chip tone={m.role==='cofounder'?'amber':'green'}>{roleName[m.role||'member']||'Участник'}</Chip><Dots/></div>)}{q.data.invites.map((i:any)=><div className="member-setting pending" key={i.id}><span className="avatar">…</span><div><b>{i.display_name||i.email}</b><small>{i.email}</small></div><Chip tone="gray">Ожидает</Chip></div>)}</div><form className="invite-form" onSubmit={e=>{e.preventDefault();if(invite.email)inviteMut.mutate()}}><h3>Добавить участника</h3><label>Email<input type="email" value={invite.email} onChange={e=>setInvite({...invite,email:e.target.value})} placeholder="name@company.com"/></label><label>Отображаемое имя<input value={invite.display_name} onChange={e=>setInvite({...invite,display_name:e.target.value})} placeholder="Например, Анна Иванова"/></label><label>Роль<select value={invite.role} onChange={e=>setInvite({...invite,role:e.target.value})}><option value="member">Участник</option><option value="manager">Менеджер</option><option value="guest">Гость</option><option value="cofounder">Сооснователь</option></select></label><Button disabled={!invite.email}>➤ Пригласить участника</Button><small>Если аккаунт уже существует в Supabase Auth, он будет добавлен сразу. Иначе приглашение сохранится как ожидающее.</small></form></div></Card><Card title="GitHub интеграция"><div className="github-status"><span className="github-logo">●</span><div><b>GitHub</b><small className="green-text">● Подключено</small></div></div>{q.data.repos.map((r:Repo)=><div className="repo-row" key={r.id}><span>◫</span><div><b>{r.full_name}</b><small>{r.last_synced_at?`Обновлено ${new Date(r.last_synced_at).toLocaleString('ru-RU')}`:'Ещё не синхронизировался'}</small></div><button className="icon-btn" onClick={()=>sync.mutate(r.id)}>↻</button></div>)}<form className="inline-form" onSubmit={e=>{e.preventDefault();if(repo.includes('/'))addRepo.mutate()}}><input value={repo} onChange={e=>setRepo(e.target.value)} placeholder="owner/repository"/><Button kind="secondary">＋ Подключить</Button></form></Card><Card title="Безопасность и данные"><div className="settings-actions"><button onClick={()=>void downloadExport()}><span>⇩</span><div><b>Экспорт данных</b><small>Скачайте данные проекта: задачи, файлы, участники, настройки.</small></div></button><button className="logout" onClick={()=>void supabase.auth.signOut()}><span>↪</span><div><b>Выход из аккаунта</b><small>Ваши данные сохранятся.</small></div></button></div></Card></div></>
}
function QuickLinkEditor({kind,link,onDone}:{kind:string;link?:QuickLink;onDone:()=>void}){const [url,setUrl]=useState(link?.url||'');const [title,setTitle]=useState(link?.title||({landing:'Лендинг Друка',telegram:'Друк в Telegram',presentation:'Презентация'} as any)[kind]);async function save(){if(link)await api(`/links/${link.id}`,json('PATCH',{url,title}));else await api('/links',json('POST',{url,title,kind}));onDone()}return <div className="link-edit"><span className="quick-icon">{kind==='telegram'?'➤':kind==='presentation'?'▤':'◎'}</span><div><input value={title} onChange={e=>setTitle(e.target.value)}/><input value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://..."/></div><button className="icon-btn" onClick={()=>void save()}>✓</button></div>}
async function downloadExport(){const data:any=await api('/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='druk-export.json';a.click();URL.revokeObjectURL(a.href)}

function NatureNote({text,image='hero-home.webp'}:{text:string;image?:string}){return <div className="nature-note" style={{backgroundImage:`linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,247,232,.3)),url(${asset(image)})`}}><span>{text} 🌱</span></div>}
